#!/bin/sh
# app1: server in tenant prod, VLAN 11, cabled to leaf3. Generated by fabctl render.
# Its gateway 10.10.11.1 is the anycast gateway: the same address and MAC on every leaf.
set -e
ip link set eth1 mtu 1500 up
ip addr replace 10.10.11.11/24 dev eth1
ip route replace default via 10.10.11.1
